/* Loads backend/.env (development secrets, generated by scripts/genenv.mjs, never committed).
   Production reads the same names from AWS Secrets Manager and replaces KEK_HEX with AWS KMS. */
import { readFileSync, existsSync } from 'node:fs';

const file = new URL('../.env', import.meta.url);
const fromFile: Record<string, string> = {};
if (existsSync(file)) for (const line of readFileSync(file, 'utf8').split('\n')) { const m = line.match(/^([A-Z0-9_]+)=(\S*)/); if (m) fromFile[m[1]] = m[2]; }
const get = (k: string, d?: string) => { const v = process.env[k] ?? fromFile[k] ?? d; if (v == null) throw new Error(`missing ${k} (run: npm run db:start)`); return v; };

export const env = {
  PGPORT: +get('PGPORT', '54329'),
  OWNER_PASSWORD: get('OWNER_PASSWORD'),
  APP_PASSWORD: get('APP_PASSWORD'),
  KEK_HEX: get('KEK_HEX'),
  INDEX_KEY_HEX: get('INDEX_KEY_HEX'),
  SESSION_PEPPER_HEX: get('SESSION_PEPPER_HEX'),
  API_PORT: +get('API_PORT', '8787'),
  APP_ORIGIN: get('APP_ORIGIN', 'http://localhost:8765'),
  PRODUCTION: get('NODE_ENV', 'development') === 'production',
  IDLE_MINUTES: +get('IDLE_MINUTES', '15'),
  BTG_HOURS: +get('BTG_HOURS', '4')
};
